//! Full-pinyin scheme indexes: the pinned `luoma_pinyin_index` and
//! `secondary_zhuyin_index`.
//!
//! Generated by `just rust-tables` from libpinyin `074a2219`:
//! `src/storage/pinyin_parser_table.h:674/1083`, joined to canonical
//! spellings through `content_table`. Both indexes are plain
//! `IS_PINYIN` spelling→content maps — no correction aliases, no
//! incomplete rows, no ambiguities — and both match their
//! `content_table` spelling columns exactly. Source-embedded tables,
//! copyable under the project source policy; not model-archive data.

use crate::static_strings::StringTable;

/// An indexed full-pinyin spelling table, decoded on demand.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct FullPinyinIndex(StringTable<2>);

impl FullPinyinIndex {
    /// Canonical pinyin for an exact input spelling.
    #[must_use]
    pub(crate) fn canonical(self, spelling: &str) -> Option<&'static str> {
        self.0.field(self.0.position(spelling)?, 1)
    }
}

/// Luoma input spellings and canonical pinyin, in pinned byte order.
#[must_use]
pub(crate) const fn luoma_pinyin_index() -> FullPinyinIndex {
    FullPinyinIndex(crate::string_tables::luoma_pinyin_index())
}

/// Secondary-zhuyin input spellings and canonical pinyin, in pinned byte order.
#[must_use]
pub(crate) const fn secondary_zhuyin_index() -> FullPinyinIndex {
    FullPinyinIndex(crate::string_tables::secondary_zhuyin_index())
}

/// Lookahead bound of the pinned full-pinyin DP, tone digit included
/// (`max_full_pinyin_length`, `pinyin_parser2.cpp:82`).
const MAX_LOOKAHEAD: usize = 7;

/// One parsed key: the canonical spelling the input segment maps to,
/// its raw byte span (tone digit included), and the parsed tone.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct FullPinyinIndexKey {
    canonical: &'static str,
    start: usize,
    end: usize,
    tone: u8,
}

impl FullPinyinIndexKey {
    /// The canonical full-pinyin spelling this segment resolves to.
    #[must_use]
    pub const fn canonical(&self) -> &'static str {
        self.canonical
    }

    /// Inclusive byte offset of the segment's first input byte.
    #[must_use]
    pub const fn start(&self) -> usize {
        self.start
    }

    /// Exclusive byte offset one past the segment's last input byte
    /// (tone digit included).
    #[must_use]
    pub const fn end(&self) -> usize {
        self.end
    }

    /// Tone number (1..5), or 0 for zero tone.
    #[must_use]
    pub const fn tone(&self) -> u8 {
        self.tone
    }
}

// FullPinyinParser2::parse and final_step, pinyin_parser2.cpp:217–251,279–310,332–380.
// The pin uses signed 16-bit parse steps; this index stores positions and counts in
// usize.
/// The selected keys and consumed byte prefix for an alternate full-pinyin spelling
/// index. Within the native parser's representable input range, the longest reachable
/// prefix wins, followed by the fewest keys and the first equal choice. Apostrophes
/// consume bytes without producing a key. A key's span includes its tone digit.
///
/// The parser considers up to seven bytes from each position, stopping at the next
/// apostrophe. Its final tie breaker is distance, which is always zero for these
/// indexes. Keeping the first equal step selects the earliest start and thus the
/// longest spelling at that step (`pinyin_parser2.cpp:222-381`).
///
/// Under the complete option word, `FORCE_TONE` requires a tone only when
/// `USE_TONE` is also set (pin 074a2219 `pinyin_parser2.cpp:176-190`). Other
/// option bits do not gate these rows. A rejected key ends the parsed prefix.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct FullPinyinIndexParse {
    keys: Vec<FullPinyinIndexKey>,
    consumed: usize,
}

impl FullPinyinIndexParse {
    /// The parsed keys in input order.
    #[must_use]
    pub fn keys(&self) -> &[FullPinyinIndexKey] {
        &self.keys
    }

    /// Number of original input bytes consumed.
    #[must_use]
    pub const fn consumed(&self) -> usize {
        self.consumed
    }
}

/// One reached dynamic-programming step of the pinned full-pinyin parse.
/// Every path to a step covers each input byte before it, so the pin's
/// `m_parsed_len` is the step's own position.
#[derive(Clone, Copy, Debug)]
struct Step {
    /// Previous step of the best path (the DP's `m_last_step`).
    last: usize,
    /// Keys on the best path (apostrophes excluded, like upstream).
    num_keys: usize,
    /// The last key the best path appended, `None` for apostrophe hops.
    key: Option<FullPinyinIndexKey>,
}

/// Stores `value` at `slot` when the slot is not reached yet or `value`
/// has fewer keys. Both cover the same input, so an equal proposal does not
/// replace, and the earlier path stays.
fn propose(slot: &mut Option<Step>, value: Step) {
    if slot.is_none_or(|existing| value.num_keys < existing.num_keys) {
        *slot = Some(value);
    }
}

/// `FullPinyinParser2::parse_one_key` over an index
/// (`pinyin_parser2.cpp:155-205`): under `use_tone` a trailing digit
/// 1..5 is the tone and is consumed with the match; the whole substring
/// must resolve through the index (plain rows only — these indexes have
/// no option-gated rows). The key spans `start..start + input.len()`.
fn parse_one_index_key(
    input: &[u8],
    start: usize,
    options: crate::OptionBits,
    index: FullPinyinIndex,
) -> Option<FullPinyinIndexKey> {
    let use_tone = options.contains(crate::OptionBits::USE_TONE);
    let mut parsed_len = input.len();
    let mut tone = 0;
    if use_tone && parsed_len > 0 && matches!(input[parsed_len - 1], b'1'..=b'5') {
        tone = input[parsed_len - 1] - b'0';
        parsed_len -= 1;
    }
    if parsed_len == 0 || (use_tone && options.contains(crate::OptionBits::FORCE_TONE) && tone == 0)
    {
        return None;
    }

    let spelling = core::str::from_utf8(input.get(..parsed_len)?).ok()?;
    Some(FullPinyinIndexKey {
        canonical: index.canonical(spelling)?,
        start,
        end: start + input.len(),
        tone,
    })
}

/// Parses an alternate spelling index with the selection rules of
/// [`FullPinyinIndexParse`] (`FullPinyinParser2::parse` and `final_step`,
/// `pinyin_parser2.cpp:222-381`).
#[must_use]
pub(crate) fn parse_full_pinyin_index_with_options(
    input: &[u8],
    options: crate::OptionBits,
    index: FullPinyinIndex,
) -> FullPinyinIndexParse {
    let mut steps: Vec<Option<Step>> = vec![None; input.len() + 1];
    steps[0] = Some(Step {
        last: 0,
        num_keys: 0,
        key: None,
    });

    // The end of the separator-free run the walk is in: found once per run
    // and forgotten at each separator, as the pin's `next_sep`
    // (`pinyin_parser2.cpp:233`, `:249`, `:253-261` at 074a2219).
    let mut run_end = None;
    for position in 0..input.len() {
        if input[position] == b'\'' {
            run_end = None;
            // Propagate the current step past the separator.
            if let Some(previous) = steps[position] {
                propose(
                    &mut steps[position + 1],
                    Step {
                        last: position,
                        num_keys: previous.num_keys,
                        key: None,
                    },
                );
            }
            continue;
        }

        let next_sep = *run_end.get_or_insert_with(|| {
            position
                + input[position..]
                    .iter()
                    .position(|&byte| byte == b'\'')
                    .unwrap_or(input.len() - position)
        });
        let try_end = (position + MAX_LOOKAHEAD).min(next_sep);
        for end in (position + 1)..=try_end {
            let Some(key) = parse_one_index_key(&input[position..end], position, options, index)
            else {
                continue;
            };
            let Some(previous) = steps[position] else {
                continue;
            };
            propose(
                &mut steps[end],
                Step {
                    last: position,
                    num_keys: previous.num_keys + 1,
                    key: Some(key),
                },
            );
        }
    }

    // final_step: the longest covered prefix from the input's start.
    let best = steps.iter().rposition(Option::is_some).unwrap_or(0);

    let mut keys = Vec::new();
    let mut cursor = best;
    // Every step on the best path is reached.
    while let (true, Some(step)) = (cursor != 0, steps[cursor]) {
        if let Some(key) = step.key {
            keys.push(key);
        }
        cursor = step.last;
    }
    keys.reverse();

    FullPinyinIndexParse {
        keys,
        consumed: best,
    }
}

